-- Homecoming 2026 check-in: full setup for a NEW, empty Supabase project (schema + security + RPCs + FAKE test data).
-- Generated by concatenating supabase/migrations/*.sql and supabase/seed_dev.sql. Run once.

-- ===== migrations/20261122000001_schema.sql =====
-- Homecoming 2026 check-in: schema. Run migrations in filename order.
-- Source: build spec section 6.

create extension if not exists citext;
create extension if not exists pgcrypto;

create type app_role     as enum ('volunteer','staff','admin');   -- order matters (comparisons)
create type ynm          as enum ('no','yes','maybe');
create type parking_type as enum ('none','two_wheeler','four_wheeler');
create type party_source as enum ('booked','onspot');
create type event_action as enum ('pass','void');

create sequence change_seq;
create sequence event_seq;

-- Allowlist + roles. Insert your first admin by hand (see supabase/seed_admin.sql).
create table staff_users (
  id uuid primary key default gen_random_uuid(),
  email citext not null unique,
  display_name text,
  role app_role not null,
  active boolean not null default true,
  auth_user_id uuid unique references auth.users(id),   -- linked at first login by whoami()
  created_by uuid references staff_users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  last_seen_at timestamptz
);

create table checkpoints (
  code text primary key,
  label text not null,
  requires text references checkpoints(code),
  counted boolean not null default false,
  sort int not null
);
insert into checkpoints (code, label, requires, counted, sort) values
  ('entry','Entry',null,false,1),
  ('dinner','Dinner','entry',true,2);

create table counters (
  code text primary key,           -- 'GATE-1','DINNER-1'..'DINNER-10'
  label text not null,
  kind text not null check (kind in ('gate','dinner','desk')),
  active boolean not null default true
);
insert into counters (code, label, kind)
  select 'GATE-' || i, 'Gate desk ' || i, 'gate' from generate_series(1, 2) i
  union all
  select 'DINNER-' || i, 'Counter ' || i, 'dinner' from generate_series(1, 10) i;

create table event_settings (      -- single row
  id boolean primary key default true check (id),
  event_name text not null default 'Homecoming 2026',
  event_date date not null default '2026-12-12',
  timezone text not null default 'Asia/Kolkata',
  is_live boolean not null default false,        -- true => reset scripts refuse to run
  deploy_freeze boolean not null default false,  -- true => no app-update prompts
  min_app_version text,
  updated_at timestamptz not null default now()
);
insert into event_settings default values;

create table import_batches (
  id uuid primary key default gen_random_uuid(),
  filename text, row_count int, created_at timestamptz not null default now()
);

create table parties (
  id uuid primary key,                           -- client-generated for on-spot
  pass_code text not null unique,
  qr_token  text not null unique,
  source party_source not null default 'booked',
  lead_name text not null,
  batch_year int not null check (batch_year between 1950 and 2100),
  decade int generated always as ((batch_year/10)*10) stored,
  school text,
  department text,
  course text,
  mobile_last4 text,
  spouse ynm not null default 'no',
  children int not null default 0 check (children between 0 and 10),
  party_size int generated always as
    (1 + (case when spouse <> 'no' then 1 else 0 end) + children) stored,
  entitled_override int check (entitled_override >= 0),
  parking parking_type not null default 'none',
  accommodation ynm,
  notes text,
  registration_status text,
  possible_duplicate_of uuid references parties(id),
  import_batch_id uuid references import_batches(id),
  deleted_at timestamptz,
  created_by uuid references staff_users(id),
  created_at timestamptz not null default now(),
  updated_by uuid references staff_users(id),
  updated_at timestamptz not null default now(),
  change_seq bigint not null default nextval('change_seq')
);
create index on parties (change_seq);
create index on parties (batch_year);
create index on parties (lower(lead_name));

-- PII lives here: Staff+ only.
create table party_contacts (
  party_id uuid primary key references parties(id),
  mobile text, email citext
);
create index on party_contacts (mobile);

create table scan_events (                       -- APPEND-ONLY
  id uuid primary key,                           -- client UUID = idempotency key
  seq bigint not null default nextval('event_seq'),
  party_id uuid not null references parties(id),
  checkpoint text not null references checkpoints(code),
  action event_action not null default 'pass',
  qty int not null default 1 check (qty >= 0),   -- entry: headcount; dinner: servings
  voids_event_id uuid references scan_events(id),
  reason text,
  override_reason text,
  method text not null check (method in ('qr','search','code','staff')),
  actor_id uuid not null references staff_users(id),
  counter text references counters(code),
  device_id uuid not null,
  client_at timestamptz not null,                -- device clock (untrusted for ordering)
  received_at timestamptz not null default now(),
  app_version text,
  check (action = 'pass' or (voids_event_id is not null and reason is not null))
);
create index on scan_events (seq);
create index on scan_events (party_id);
create unique index one_void_per_event on scan_events (voids_event_id) where action = 'void';

create function forbid_mutation() returns trigger language plpgsql as
$$ begin raise exception 'scan_events is append-only'; end $$;
create trigger scan_events_no_update before update or delete on scan_events
  for each row execute function forbid_mutation();

create table review_resolutions (                -- append-only
  id uuid primary key default gen_random_uuid(),
  party_id uuid not null references parties(id),
  note text, resolved_by uuid references staff_users(id),
  resolved_at timestamptz not null default now()
);

create table device_status (
  device_id uuid primary key,
  user_id uuid references staff_users(id),
  counter text, pending_count int, app_version text,
  last_sync_at timestamptz, clock_offset_ms int
);

create table audit_log (                         -- append-only; filled by triggers/RPCs
  id bigserial primary key,
  at timestamptz not null default now(),
  actor_id uuid references staff_users(id),
  table_name text not null, row_id text not null,
  action text not null, before jsonb, after jsonb, reason text
);

-- Derived state. The TypeScript partyState() in src/lib/state.ts must agree with this view.
create view party_state with (security_invoker = true) as
with live as (
  select e.* from scan_events e
  where e.action = 'pass'
    and not exists (select 1 from scan_events v
                    where v.action = 'void' and v.voids_event_id = e.id)
),
entry as (
  select distinct on (party_id) party_id, client_at as entered_at, qty as headcount, counter
  from live where checkpoint = 'entry'
  order by party_id, client_at, received_at          -- earliest wins
),
entry_n as (select party_id, count(*) n from live where checkpoint='entry' group by 1),
dinner as (
  select party_id, sum(qty)::int as served, max(client_at) as last_served_at
  from live where checkpoint = 'dinner' group by party_id
)
select p.id as party_id,
  coalesce(p.entitled_override, p.party_size)               as entitled,
  (en.party_id is not null)                                 as entered,
  en.entered_at, en.headcount,
  coalesce(d.served,0)                                      as served,
  d.last_served_at,
  coalesce(d.served,0) > coalesce(p.entitled_override,p.party_size) as over_served,
  (coalesce(d.served,0) > 0 and en.party_id is null)        as served_without_entry,
  coalesce(n.n,0) > 1                                       as duplicate_entry,
  (p.possible_duplicate_of is not null)                     as possible_duplicate
from parties p
left join entry en on en.party_id = p.id
left join entry_n n on n.party_id = p.id
left join dinner d on d.party_id = p.id
where p.deleted_at is null;

-- ===== migrations/20261122000002_security.sql =====
-- Helpers, triggers, RLS and grants. Build spec section 7.

create function current_staff() returns staff_users
language sql stable security definer set search_path = public as
$$ select * from staff_users where auth_user_id = auth.uid() and active limit 1 $$;

create function is_active_staff() returns boolean
language sql stable security definer set search_path = public as
$$ select exists (select 1 from staff_users where auth_user_id = auth.uid() and active) $$;

create function has_role(min_role app_role) returns boolean
language sql stable security definer set search_path = public as
$$ select exists (select 1 from staff_users where auth_user_id = auth.uid() and active and role >= min_role) $$;

-- Audit: every change to the tables below is copied to audit_log. RPCs may set app.reason first.
create function audit_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  b jsonb; a jsonb;
  noise text[] := array['updated_at','change_seq','last_seen_at'];
begin
  if tg_op <> 'INSERT' then b := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then a := to_jsonb(new); end if;
  if tg_op = 'UPDATE' and (a - noise) = (b - noise) then return new; end if;
  insert into audit_log (actor_id, table_name, row_id, action, before, after, reason)
  values (
    (select id from staff_users where auth_user_id = auth.uid() limit 1),
    tg_table_name, coalesce(a, b) ->> tg_argv[0], lower(tg_op), b, a,
    nullif(current_setting('app.reason', true), '')
  );
  return coalesce(new, old);
end $$;

create trigger audit_parties        after insert or update or delete on parties        for each row execute function audit_row('id');
create trigger audit_staff_users    after insert or update or delete on staff_users    for each row execute function audit_row('id');
create trigger audit_event_settings after insert or update or delete on event_settings for each row execute function audit_row('id');
create trigger audit_party_contacts after insert or update or delete on party_contacts for each row execute function audit_row('party_id');

create function stamp_party() returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' then
    new.updated_at := now();
    new.change_seq := nextval('change_seq');
  end if;
  return new;
end $$;
create trigger parties_stamp before update on parties for each row execute function stamp_party();

-- Never lose the last active admin.
create function guard_last_admin() returns trigger language plpgsql as $$
begin
  if old.role = 'admin' and old.active
     and (tg_op = 'DELETE' or new.role <> 'admin' or not new.active) then
    if not exists (select 1 from staff_users where role = 'admin' and active and id <> old.id) then
      raise exception 'Cannot remove, demote or deactivate the last active admin';
    end if;
  end if;
  return coalesce(new, old);
end $$;
create trigger staff_users_last_admin before update or delete on staff_users
  for each row execute function guard_last_admin();

-- RLS on every table. No INSERT/UPDATE/DELETE policies: all writes go through the RPCs.
alter table staff_users        enable row level security;
alter table checkpoints        enable row level security;
alter table counters           enable row level security;
alter table event_settings     enable row level security;
alter table import_batches     enable row level security;
alter table parties            enable row level security;
alter table party_contacts     enable row level security;
alter table scan_events        enable row level security;
alter table review_resolutions enable row level security;
alter table device_status      enable row level security;
alter table audit_log          enable row level security;

create policy read_parties    on parties        for select to authenticated using (is_active_staff());
create policy read_events     on scan_events    for select to authenticated using (is_active_staff());
create policy read_checkpts   on checkpoints    for select to authenticated using (is_active_staff());
create policy read_counters   on counters       for select to authenticated using (is_active_staff());
create policy read_settings   on event_settings for select to authenticated using (is_active_staff());
create policy read_contacts   on party_contacts     for select to authenticated using (has_role('staff'));
create policy read_resolved   on review_resolutions for select to authenticated using (has_role('staff'));
create policy read_devices    on device_status      for select to authenticated using (has_role('staff'));
create policy read_users      on staff_users    for select to authenticated using (has_role('admin') or auth_user_id = auth.uid());
create policy read_audit      on audit_log      for select to authenticated using (has_role('admin'));
create policy read_batches    on import_batches for select to authenticated using (has_role('admin'));

-- Grants: read only, for signed-in users. Nothing for anon. Writes only via RPCs.
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant select on parties, scan_events, checkpoints, counters, event_settings, party_contacts,
  review_resolutions, device_status, staff_users, audit_log, import_batches, party_state to authenticated;
grant execute on function current_staff(), is_active_staff(), has_role(app_role) to authenticated;

-- ===== migrations/20261122000003_rpc.sql =====
-- RPCs. Build spec section 7. All SECURITY DEFINER with a fixed search_path; the caller is
-- always identified from auth.uid(), never from anything the client sends.

create function _require_staff() returns staff_users language plpgsql stable security definer set search_path = public as $$
declare me staff_users;
begin
  select * into me from staff_users where auth_user_id = auth.uid() and active;
  if not found then raise exception 'not authorised' using errcode = '42501'; end if;
  return me;
end $$;

create function _require_role(min_role app_role) returns staff_users language plpgsql stable security definer set search_path = public as $$
declare me staff_users := _require_staff();
begin
  if me.role < min_role then raise exception 'not authorised' using errcode = '42501'; end if;
  return me;
end $$;

-- Links the signed-in auth user to the allowlist by verified email. null => "Not authorised".
create function whoami() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); em text; ok boolean; s staff_users;
begin
  if uid is null then return null; end if;
  select lower(u.email), (u.email_confirmed_at is not null) into em, ok from auth.users u where u.id = uid;
  if em is null or not ok then return null; end if;
  select * into s from staff_users where email = em;
  if not found then return null; end if;
  if not s.active then return jsonb_build_object('active', false); end if;
  if s.auth_user_id is not null and s.auth_user_id <> uid then return null; end if;
  update staff_users set auth_user_id = uid, last_seen_at = now() where id = s.id returning * into s;
  return jsonb_build_object('id', s.id, 'email', s.email, 'role', s.role, 'active', true,
                            'name', coalesce(s.display_name, split_part(s.email::text, '@', 1)));
end $$;

-- Paged pull, used for the first download and for later catch-up. No PII: roster rows only.
create function get_snapshot(p_party_after bigint default 0, p_event_after bigint default 0, p_limit int default 1000)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare ps jsonb; es jsonb; pc bigint; ec bigint; pn int; en int;
begin
  perform _require_staff();
  select coalesce(jsonb_agg(to_jsonb(x) order by x.change_seq), '[]'::jsonb), coalesce(max(x.change_seq), p_party_after), count(*)
    into ps, pc, pn
  from (select id, pass_code, qr_token, source, lead_name, batch_year, school, department, course, mobile_last4,
               spouse, children, party_size, entitled_override, parking, possible_duplicate_of, deleted_at, change_seq
        from parties where change_seq > p_party_after order by change_seq limit p_limit) x;
  select coalesce(jsonb_agg(to_jsonb(y) order by y.seq), '[]'::jsonb), coalesce(max(y.seq), p_event_after), count(*)
    into es, ec, en
  from (select e.id, e.seq, e.party_id, e.checkpoint, e.action, e.qty, e.voids_event_id, e.reason, e.override_reason,
               e.method, e.actor_id, coalesce(s.display_name, split_part(s.email::text, '@', 1)) as actor_name, e.counter,
               e.device_id, (extract(epoch from e.client_at) * 1000)::bigint as client_at,
               (extract(epoch from e.received_at) * 1000)::bigint as received_at
        from scan_events e left join staff_users s on s.id = e.actor_id
        where e.seq > p_event_after order by e.seq limit p_limit) y;
  return jsonb_build_object('parties', ps, 'events', es, 'party_cursor', pc, 'event_cursor', ec,
                            'more', (pn = p_limit or en = p_limit));
end $$;

create function _push_party(me staff_users, p jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare pt jsonb := p->'party'; ct jsonb := p->'contact'; pid uuid := (pt->>'id')::uuid; digits text; mob text; dup uuid;
begin
  if exists (select 1 from parties where id = pid) then return '{"status":"duplicate"}'::jsonb; end if;
  digits := right(regexp_replace(coalesce(ct->>'mobile', ''), '\D', '', 'g'), 10);
  if length(digits) <> 10 then raise exception 'Mobile needs 10 digits'; end if;
  mob := '+91' || digits;
  -- Same mobile as an existing party: still create it, but flag it. Never auto-merge.
  select party_id into dup from party_contacts where mobile = mob limit 1;
  insert into parties (id, pass_code, qr_token, source, lead_name, batch_year, school, department, course, mobile_last4,
                       spouse, children, parking, possible_duplicate_of, created_by, updated_by)
  values (pid, pt->>'passCode', pt->>'qrToken', 'onspot', btrim(pt->>'leadName'), (pt->>'batchYear')::int,
          pt->>'school', pt->>'department', pt->>'course', right(digits, 4),
          (pt->>'spouse')::ynm, (pt->>'children')::int, coalesce(pt->>'parking', 'none')::parking_type, dup, me.id, me.id);
  insert into party_contacts (party_id, mobile, email) values (pid, mob, nullif(btrim(ct->>'email'), ''));
  return '{"status":"accepted"}'::jsonb;
end $$;

create function _push_event(me staff_users, p jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  eid uuid := (p->>'id')::uuid;
  act event_action := coalesce(p->>'action', 'pass')::event_action;
  vid uuid := nullif(p->>'voidsEventId', '')::uuid;
  cat timestamptz := to_timestamp((p->>'clientAt')::numeric / 1000.0);
  tgt scan_events;
begin
  if exists (select 1 from scan_events where id = eid) then return '{"status":"duplicate"}'::jsonb; end if;
  if not exists (select 1 from parties where id = (p->>'partyId')::uuid) then raise exception 'Unknown party'; end if;
  if me.role = 'volunteer' and (p->>'method' = 'staff' or nullif(p->>'overrideReason', '') is not null) then
    raise exception 'Staff only';
  end if;
  if act = 'void' then
    select * into tgt from scan_events where id = vid;
    if not found then raise exception 'Nothing to undo'; end if;
    if exists (select 1 from scan_events where voids_event_id = vid) then raise exception 'Already undone'; end if;
    if me.role = 'volunteer' then
      if tgt.actor_id <> me.id then raise exception 'You can only undo your own scans'; end if;
      if cat - tgt.client_at > interval '120 seconds' then raise exception 'Undo window has passed'; end if;
    end if;
  end if;
  insert into scan_events (id, party_id, checkpoint, action, qty, voids_event_id, reason, override_reason, method,
                           actor_id, counter, device_id, client_at, app_version)
  values (eid, (p->>'partyId')::uuid, p->>'checkpoint', act, coalesce((p->>'qty')::int, 1), vid,
          nullif(p->>'reason', ''), nullif(p->>'overrideReason', ''), p->>'method',
          me.id, nullif(p->>'counter', ''), (p->>'deviceId')::uuid, cat, p->>'appVersion');
  return '{"status":"accepted"}'::jsonb;
end $$;

-- Ordered batch from the phone's outbox. One bad item never blocks the others.
create function push_batch(items jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_staff(); it jsonb; r jsonb; res jsonb := '[]'::jsonb;
begin
  perform pg_advisory_xact_lock(1);   -- seq / change_seq order == commit order, so cursor pulls are safe
  for it in select value from jsonb_array_elements(items) loop
    begin
      r := case it->>'type'
             when 'party' then _push_party(me, it->'payload')
             when 'event' then _push_event(me, it->'payload')
             else jsonb_build_object('status', 'rejected', 'reason', 'Unknown item type') end;
    exception when others then
      r := jsonb_build_object('status', 'rejected', 'reason', sqlerrm);
    end;
    res := res || jsonb_build_array(jsonb_build_object('id', it->>'id') || r);
  end loop;
  return res;
end $$;

create function device_heartbeat(p_device_id uuid, p_counter text, p_pending_count int, p_app_version text, p_client_now timestamptz)
returns void language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_staff();
begin
  insert into device_status (device_id, user_id, counter, pending_count, app_version, last_sync_at, clock_offset_ms)
  values (p_device_id, me.id, p_counter, p_pending_count, p_app_version, now(),
          (extract(epoch from (now() - p_client_now)) * 1000)::int)
  on conflict (device_id) do update set user_id = excluded.user_id, counter = excluded.counter,
    pending_count = excluded.pending_count, app_version = excluded.app_version,
    last_sync_at = excluded.last_sync_at, clock_offset_ms = excluded.clock_offset_ms;
end $$;

-- Staff and up -------------------------------------------------------------------------------

create function get_party_contact(p_party_id uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('staff'); c party_contacts;
begin
  select * into c from party_contacts where party_id = p_party_id;
  insert into audit_log (actor_id, table_name, row_id, action) values (me.id, 'party_contacts', p_party_id::text, 'read');
  return jsonb_build_object('mobile', c.mobile, 'email', c.email);
end $$;

create function resolve_review(p_party_id uuid, p_note text) returns void language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('staff');
begin
  insert into review_resolutions (party_id, note, resolved_by) values (p_party_id, p_note, me.id);
end $$;

create function update_party(p_id uuid, p_patch jsonb, p_reason text) returns void language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('staff');
begin
  if coalesce(btrim(p_reason), '') = '' then raise exception 'A reason is required'; end if;
  perform set_config('app.reason', p_reason, true);
  update parties set
    lead_name         = coalesce(p_patch->>'lead_name', lead_name),
    batch_year        = coalesce((p_patch->>'batch_year')::int, batch_year),
    school            = coalesce(p_patch->>'school', school),
    department        = coalesce(p_patch->>'department', department),
    course            = coalesce(p_patch->>'course', course),
    spouse            = coalesce((p_patch->>'spouse')::ynm, spouse),
    children          = coalesce((p_patch->>'children')::int, children),
    entitled_override = case when p_patch ? 'entitled_override' then (p_patch->>'entitled_override')::int else entitled_override end,
    parking           = coalesce((p_patch->>'parking')::parking_type, parking),
    notes             = coalesce(p_patch->>'notes', notes),
    updated_by        = me.id
  where id = p_id;
  if not found then raise exception 'Unknown party'; end if;
end $$;

-- Admin only ---------------------------------------------------------------------------------

create function admin_set_user(p_email text, p_name text, p_role app_role, p_active boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('admin'); s staff_users;
begin
  if coalesce(btrim(p_email), '') !~ '^[^@\s]+@[^@\s]+$' then raise exception 'Enter a valid email'; end if;
  insert into staff_users (email, display_name, role, active, created_by)
  values (lower(btrim(p_email)), nullif(btrim(p_name), ''), p_role, p_active, me.id)
  on conflict (email) do update set display_name = excluded.display_name, role = excluded.role,
    active = excluded.active, updated_at = now()
  returning * into s;
  return jsonb_build_object('email', s.email, 'name', coalesce(s.display_name, ''), 'role', s.role, 'active', s.active);
end $$;

create function admin_list_users() returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_role('admin');
  return coalesce((select jsonb_agg(jsonb_build_object('email', email, 'name', coalesce(display_name, ''), 'role', role, 'active', active)
                                    order by role desc, email) from staff_users), '[]'::jsonb);
end $$;

create function audit_feed(p_limit int default 100, p_before bigint default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_role('admin');
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.id desc) from (
    select a.id, a.at, s.email as actor_email, a.table_name, a.row_id, a.action, a.before, a.after, a.reason
    from audit_log a left join staff_users s on s.id = a.actor_id
    where p_before is null or a.id < p_before order by a.id desc limit least(p_limit, 500)) x), '[]'::jsonb);
end $$;

-- Only the public RPCs are callable by signed-in users. The _helpers stay private.
revoke execute on function _require_staff(), _require_role(app_role), _push_party(staff_users, jsonb), _push_event(staff_users, jsonb) from public, anon, authenticated;
grant execute on function whoami(), get_snapshot(bigint, bigint, int), push_batch(jsonb),
  device_heartbeat(uuid, text, int, text, timestamptz), get_party_contact(uuid), resolve_review(uuid, text),
  update_party(uuid, jsonb, text), admin_set_user(text, text, app_role, boolean), admin_list_users(),
  audit_feed(int, bigint) to authenticated;

-- ===== migrations/20261122000004_update_party_lock.sql =====
-- update_party bumps change_seq, so it takes the same lock as push_batch.
-- Without it, an edit could commit out of change_seq order and a phone's cursor pull could skip that row for good.
create or replace function update_party(p_id uuid, p_patch jsonb, p_reason text) returns void language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('staff');
begin
  if coalesce(btrim(p_reason), '') = '' then raise exception 'A reason is required'; end if;
  perform pg_advisory_xact_lock(1);
  perform set_config('app.reason', p_reason, true);
  update parties set
    lead_name         = coalesce(p_patch->>'lead_name', lead_name),
    batch_year        = coalesce((p_patch->>'batch_year')::int, batch_year),
    school            = coalesce(p_patch->>'school', school),
    department        = coalesce(p_patch->>'department', department),
    course            = coalesce(p_patch->>'course', course),
    spouse            = coalesce((p_patch->>'spouse')::ynm, spouse),
    children          = coalesce((p_patch->>'children')::int, children),
    entitled_override = case when p_patch ? 'entitled_override' then (p_patch->>'entitled_override')::int else entitled_override end,
    parking           = coalesce((p_patch->>'parking')::parking_type, parking),
    notes             = coalesce(p_patch->>'notes', notes),
    updated_by        = me.id
  where id = p_id;
  if not found then raise exception 'Unknown party'; end if;
end $$;

-- ===== migrations/20261122000005_lock_down.sql =====
-- Lock-down pass. Safe to run on a project that already has migrations 1 to 4 (run just this file there).
--
-- 1. Signed-out visitors (the anon role) could still call the public RPCs. They were refused inside the function
--    ("not authorised"), so no data leaked, but the door itself should be shut. Migration 2 stripped function
--    grants before the RPCs of migration 3 existed, and those new functions got the Postgres/Supabase defaults.
-- 2. Staff could read every mobile number and email straight from the party_contacts table, which skipped the audit
--    row that get_party_contact writes. Contacts are now readable only through that audited function.
-- 3. Everyone signed in could read parties.notes (free text that can hold personal details) straight from the table.
--    The roster snapshot never included it. Notes are now hidden from direct reads too.
-- 4. A void event could point at another guest's scan, or at another void. Both are now rejected.

-- 1. RPC access: signed-in users only, and only the functions the app calls.
-- Postgres gives every new function EXECUTE to PUBLIC, which a schema default cannot take away, so a function added
-- later still needs its own "revoke execute ... from public, anon" (the check in test/checks.sql catches a miss).
alter default privileges in schema public revoke execute on functions from anon;
revoke execute on all functions in schema public from public, anon;
revoke execute on function audit_row(), stamp_party(), guard_last_admin(), forbid_mutation() from authenticated;
grant execute on function current_staff(), is_active_staff(), has_role(app_role), whoami(), get_snapshot(bigint, bigint, int),
  push_batch(jsonb), device_heartbeat(uuid, text, int, text, timestamptz), get_party_contact(uuid), resolve_review(uuid, text),
  update_party(uuid, jsonb, text), admin_set_user(text, text, app_role, boolean), admin_list_users(),
  audit_feed(int, bigint) to authenticated;

-- 2. Contacts only through get_party_contact (SECURITY DEFINER, so it still reads the table).
drop policy if exists read_contacts on party_contacts;
revoke select on party_contacts from authenticated;

-- 3. Everything on parties except notes.
revoke select on parties from authenticated;
grant select (id, pass_code, qr_token, source, lead_name, batch_year, decade, school, department, course, mobile_last4,
              spouse, children, party_size, entitled_override, parking, accommodation, registration_status,
              possible_duplicate_of, import_batch_id, deleted_at, created_by, created_at, updated_by, updated_at, change_seq)
  on parties to authenticated;

-- 4. Void checks. Same function as migration 3, plus two lines.
create or replace function _push_event(me staff_users, p jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  eid uuid := (p->>'id')::uuid;
  act event_action := coalesce(p->>'action', 'pass')::event_action;
  vid uuid := nullif(p->>'voidsEventId', '')::uuid;
  cat timestamptz := to_timestamp((p->>'clientAt')::numeric / 1000.0);
  tgt scan_events;
begin
  if exists (select 1 from scan_events where id = eid) then return '{"status":"duplicate"}'::jsonb; end if;
  if not exists (select 1 from parties where id = (p->>'partyId')::uuid) then raise exception 'Unknown party'; end if;
  if me.role = 'volunteer' and (p->>'method' = 'staff' or nullif(p->>'overrideReason', '') is not null) then
    raise exception 'Staff only';
  end if;
  if act = 'void' then
    select * into tgt from scan_events where id = vid;
    if not found or tgt.action <> 'pass' then raise exception 'Nothing to undo'; end if;
    if tgt.party_id <> (p->>'partyId')::uuid then raise exception 'That scan belongs to another guest'; end if;
    if exists (select 1 from scan_events where voids_event_id = vid) then raise exception 'Already undone'; end if;
    if me.role = 'volunteer' then
      if tgt.actor_id <> me.id then raise exception 'You can only undo your own scans'; end if;
      if cat - tgt.client_at > interval '120 seconds' then raise exception 'Undo window has passed'; end if;
    end if;
  end if;
  insert into scan_events (id, party_id, checkpoint, action, qty, voids_event_id, reason, override_reason, method,
                           actor_id, counter, device_id, client_at, app_version)
  values (eid, (p->>'partyId')::uuid, p->>'checkpoint', act, coalesce((p->>'qty')::int, 1), vid,
          nullif(p->>'reason', ''), nullif(p->>'overrideReason', ''), p->>'method',
          me.id, nullif(p->>'counter', ''), (p->>'deviceId')::uuid, cat, p->>'appVersion');
  return '{"status":"accepted"}'::jsonb;
end $$;

-- ===== migrations/20261122000006_signup_hook.sql =====
-- Only listed emails can create an account. Without this, any Google user who finishes the sign-in gets a row under
-- Supabase Authentication, Users (the allowlist still kept them out of every table, but the list filled with strangers).
--
-- This is a Supabase "Before User Created" auth hook. Creating the function does nothing by itself: after running this
-- file, turn it on in the dashboard (Authentication, Hooks, Before User Created, pick hook_before_user_created).
-- It runs only when a new account would be created, so people who already signed in are not affected.
-- Existing projects: run just this file.

create function hook_before_user_created(event jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from staff_users where email = lower(btrim(event->'user'->>'email'))) then
    return '{}'::jsonb;
  end if;
  -- NOT_ON_LIST is matched by the app (src/lib/signinReturn.ts) to show "You're not on the list yet".
  return jsonb_build_object('error', jsonb_build_object(
    'http_code', 403, 'message', 'NOT_ON_LIST: this account is not on the Homecoming list.'));
end $$;

-- Only Supabase Auth may run it: not the signed-out role, not signed-in users.
revoke execute on function hook_before_user_created(jsonb) from public, anon, authenticated;
grant usage on schema public to supabase_auth_admin;
grant execute on function hook_before_user_created(jsonb) to supabase_auth_admin;

-- ===== migrations/20261122000007_guest_import.sql =====
-- Guest list import and pass-list export, for admins. Run after 20261122000006.
--
-- admin_import_guests: loads a whole guest list in one transaction (all rows or none). "Add" keeps the current guests.
--   "Replace" first retires every current guest (soft delete: deleted_at is set, so phones pick the change up), and is
--   refused once the event is live or any scan exists. Pass codes and QR tokens are made here, never by the browser.
--   The work is set-based (one insert for all guests): a per-row loop that looks things up gets slower with every row,
--   and the hosted database cancels any request after about 8 seconds.
-- admin_export_passes: every current guest with their pass code, QR token and contact, for the SMS and QR print steps.
--   Each export is recorded in audit_log, like opening one guest's contact.

-- Private helpers: one random GH26-XXXXX candidate, and n different codes that no guest (current or retired) has.
create function _pass_code_candidate() returns text language plpgsql volatile set search_path = public as $$
declare alphabet constant text := '23456789ABCDEFGHJKMNPQRSTVWXYZ'; b bytea := decode(replace(gen_random_uuid()::text, '-', ''), 'hex'); c text := 'GH26-'; i int;
begin
  for i in 0..4 loop c := c || substr(alphabet, get_byte(b, i) % 30 + 1, 1); end loop;
  return c;
end $$;

create function _new_pass_codes(n int) returns text[] language plpgsql volatile set search_path = public as $$
declare codes text[] := '{}'; got text[];
begin
  loop
    select coalesce(array_agg(x.c), '{}') into got from (
      select u.c from (select distinct _pass_code_candidate() as c from generate_series(1, (n - cardinality(codes)) + (n - cardinality(codes)) / 4 + 20)) u
      where not exists (select 1 from parties p where p.pass_code = u.c) and u.c <> all (codes)
      limit n - cardinality(codes)) x;
    codes := codes || got;
    exit when cardinality(codes) >= n;
  end loop;
  return codes;
end $$;

-- p_rows: [{name, batchYear, school, department, course, mobile, email, spouse, children, parking, accommodation, dinnerOverride}]
create function admin_import_guests(p_filename text, p_rows jsonb, p_replace boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me staff_users := _require_role('admin');
  batch uuid := gen_random_uuid();
  r jsonb; n int := 0; flagged int; retired int := 0; codes text[];
  nm text; v text;
begin
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'The file has no guests'; end if;
  if jsonb_array_length(p_rows) > 10000 then raise exception 'Too many guests in one file (limit 10000). Split it and use Add.'; end if;
  -- Same lock push_batch takes: change numbers then follow commit order, so no phone can miss a row.
  perform pg_advisory_xact_lock(1);

  -- Check every row first, so a bad file changes nothing and the message names the guest.
  for r in select value from jsonb_array_elements(p_rows) loop
    n := n + 1;
    nm := btrim(coalesce(r->>'name', ''));
    if length(nm) < 2 then raise exception 'Guest %: the name is missing', n; end if;
    if coalesce(r->>'batchYear', '') !~ '^\d{4}$' then raise exception 'Guest % (%): the batch year must be a 4-digit year', n, nm; end if;
    if length(right(regexp_replace(coalesce(r->>'mobile', ''), '\D', '', 'g'), 10)) <> 10 then raise exception 'Guest % (%): the mobile needs 10 digits', n, nm; end if;
    if coalesce(nullif(r->>'spouse', ''), 'no') not in ('no', 'yes', 'maybe') then raise exception 'Guest % (%): spouse must be no, yes or maybe', n, nm; end if;
    if coalesce(nullif(r->>'parking', ''), 'none') not in ('none', 'two_wheeler', 'four_wheeler') then raise exception 'Guest % (%): parking must be none, two_wheeler or four_wheeler', n, nm; end if;
    v := nullif(r->>'accommodation', '');
    if v is not null and v not in ('no', 'yes', 'maybe') then raise exception 'Guest % (%): accommodation must be no, yes or maybe', n, nm; end if;
    v := coalesce(nullif(r->>'children', ''), '0');
    if v !~ '^\d{1,2}$' or v::int > 10 then raise exception 'Guest % (%): children must be a number from 0 to 10', n, nm; end if;
    v := nullif(r->>'dinnerOverride', '');
    if v is not null and v !~ '^\d{1,3}$' then raise exception 'Guest % (%): dinner override must be a whole number', n, nm; end if;
    v := nullif(btrim(coalesce(r->>'email', '')), '');
    if v is not null and v !~ '^[^@\s]+@[^@\s]+$' then raise exception 'Guest % (%): the email does not look right', n, nm; end if;
  end loop;

  perform set_config('app.reason', 'Guest list import' || coalesce(': ' || nullif(btrim(p_filename), ''), ''), true);
  if p_replace then
    if (select is_live from event_settings) then raise exception 'The event is live: the guest list can no longer be replaced. Use Add.'; end if;
    if exists (select 1 from scan_events) then
      raise exception 'Scans already exist, so the list cannot be replaced. Clear the test activity first (see supabase/README.md), then import again.';
    end if;
    update parties set deleted_at = now(), updated_by = me.id where deleted_at is null;
    get diagnostics retired = row_count;
  end if;

  insert into import_batches (id, filename, row_count) values (batch, nullif(btrim(p_filename), ''), n);
  codes := _new_pass_codes(n);

  -- One statement for everyone. A guest whose mobile is already on a current guest, or on an earlier row of this file,
  -- is still created but flagged (possible_duplicate_of). Never merged. Retired guests do not count.
  with rw as materialized (
    select t.n::int as n, gen_random_uuid() as pid, btrim(t.r->>'name') as nm, (t.r->>'batchYear')::int as yr,
           nullif(btrim(t.r->>'school'), '') as school, nullif(btrim(t.r->>'department'), '') as department,
           nullif(btrim(t.r->>'course'), '') as course, d.digits, '+91' || d.digits as mob,
           nullif(btrim(coalesce(t.r->>'email', '')), '') as email,
           coalesce(nullif(t.r->>'spouse', ''), 'no') as spouse, coalesce(nullif(t.r->>'children', ''), '0')::int as children,
           coalesce(nullif(t.r->>'parking', ''), 'none') as parking, nullif(t.r->>'accommodation', '') as acc,
           nullif(t.r->>'dinnerOverride', '')::int as ovr
    from jsonb_array_elements(p_rows) with ordinality as t(r, n),
         lateral (select right(regexp_replace(coalesce(t.r->>'mobile', ''), '\D', '', 'g'), 10) as digits) d
  ), existing as materialized (
    select distinct on (c.mobile) c.mobile, c.party_id
    from party_contacts c join parties p on p.id = c.party_id
    where p.deleted_at is null and p.id <> all (select pid from rw)
    order by c.mobile, p.created_at, p.id
  ), flagged_rows as materialized (
    select rw.n, rw.pid,
           coalesce(ex.party_id, case when first_value(rw.n) over w < rw.n then first_value(rw.pid) over w end) as dup
    from rw left join existing ex on ex.mobile = rw.mob
    window w as (partition by rw.mob order by rw.n)
  ), made as (
    insert into parties (id, pass_code, qr_token, source, lead_name, batch_year, school, department, course, mobile_last4,
                         spouse, children, entitled_override, parking, accommodation, possible_duplicate_of, import_batch_id,
                         created_by, updated_by)
    select rw.pid, u.code, translate(encode(decode(replace(gen_random_uuid()::text, '-', ''), 'hex'), 'base64'), '+/=', '-_'),
           'booked', rw.nm, rw.yr, rw.school, rw.department, rw.course, right(rw.digits, 4), rw.spouse::ynm, rw.children, rw.ovr,
           rw.parking::parking_type, rw.acc::ynm, f.dup, batch, me.id, me.id
    from rw join flagged_rows f on f.n = rw.n join unnest(codes) with ordinality as u(code, n) on u.n = rw.n
    returning id
  )
  insert into party_contacts (party_id, mobile, email) select rw.pid, rw.mob, rw.email from rw;

  select count(*) into flagged from parties where import_batch_id = batch and possible_duplicate_of is not null;
  return jsonb_build_object('batch', batch, 'imported', n, 'flagged', flagged, 'retired', retired);
end $$;

create function admin_export_passes() returns jsonb language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('admin'); out jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
           'pass_code', p.pass_code, 'qr_token', p.qr_token, 'lead_name', p.lead_name, 'batch_year', p.batch_year,
           'school', p.school, 'department', p.department, 'course', p.course, 'mobile_last4', p.mobile_last4,
           'spouse', p.spouse, 'children', p.children, 'party_size', p.party_size, 'parking', p.parking,
           'mobile', c.mobile, 'email', c.email) order by p.pass_code), '[]'::jsonb)
    into out
  from parties p left join party_contacts c on c.party_id = p.id
  where p.deleted_at is null;
  insert into audit_log (actor_id, table_name, row_id, action, after, reason)
  values (me.id, 'party_contacts', 'all', 'read', jsonb_build_object('guests', jsonb_array_length(out)), 'Pass list export');
  return out;
end $$;

revoke execute on function _pass_code_candidate(), _new_pass_codes(int) from public, anon, authenticated;
revoke execute on function admin_import_guests(text, jsonb, boolean), admin_export_passes() from public, anon;
grant execute on function admin_import_guests(text, jsonb, boolean), admin_export_passes() to authenticated;

-- ===== migrations/20261122000008_undo_and_heartbeat.sql =====
-- Undo window without trusting the phone's clock, and device rows that one user can't overwrite for another.
-- Safe to run on a project that already has migrations 1 to 7 (run just this file). The app works with or without it.
--
-- 1. Volunteer undo. The window compares the undo's client_at with the scan's client_at, both stamped by the phone. For
--    two scans from the same phone that stays the rule, on purpose: the clock offset cancels, and a volunteer who
--    undoes within the window while offline must still be accepted when the phone reconnects. So a volunteer can
--    still stretch the window for their own scans from their own phone by setting its clock back; that is not closed
--    and can't be without refusing legitimate offline undos. What this migration changes:
--      - an undo dated before the scan it undoes is refused (a clock set back past the scan);
--      - an undo from a different phone than the scan is judged by the server's own time (it must arrive within the
--        window of the scan arriving), because two phones' clocks can't be compared.
--    The device id is supplied by the phone, so this is about clock skew and mix-ups between phones, not a modified
--    app. Staff and admins are unaffected: they can undo any scan at any time, as before.
-- 2. device_heartbeat. The row was keyed on device_id alone and the upsert overwrote user_id, so any signed-in user who
--    knew (or guessed) another phone's device id could rewrite that phone's row. The row is now keyed on
--    (device_id, user_id): each user can only ever write their own row, and a phone handed to someone else simply gets
--    a second row.

create or replace function _push_event(me staff_users, p jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  eid uuid := (p->>'id')::uuid;
  act event_action := coalesce(p->>'action', 'pass')::event_action;
  vid uuid := nullif(p->>'voidsEventId', '')::uuid;
  cat timestamptz := to_timestamp((p->>'clientAt')::numeric / 1000.0);
  tgt scan_events;
begin
  if exists (select 1 from scan_events where id = eid) then return '{"status":"duplicate"}'::jsonb; end if;
  if not exists (select 1 from parties where id = (p->>'partyId')::uuid) then raise exception 'Unknown party'; end if;
  if me.role = 'volunteer' and (p->>'method' = 'staff' or nullif(p->>'overrideReason', '') is not null) then
    raise exception 'Staff only';
  end if;
  if act = 'void' then
    select * into tgt from scan_events where id = vid;
    if not found or tgt.action <> 'pass' then raise exception 'Nothing to undo'; end if;
    if tgt.party_id <> (p->>'partyId')::uuid then raise exception 'That scan belongs to another guest'; end if;
    if exists (select 1 from scan_events where voids_event_id = vid) then raise exception 'Already undone'; end if;
    if me.role = 'volunteer' then
      if tgt.actor_id <> me.id then raise exception 'You can only undo your own scans'; end if;
      if tgt.device_id = (p->>'deviceId')::uuid then
        -- Same phone, one clock.
        if cat < tgt.client_at then raise exception 'That undo is dated before the scan'; end if;
        if cat - tgt.client_at > interval '120 seconds' then raise exception 'Undo window has passed'; end if;
      else
        -- Another phone: its clock can't be compared with the scan's, so use ours.
        if now() - tgt.received_at > interval '120 seconds' then raise exception 'Undo window has passed'; end if;
      end if;
    end if;
  end if;
  insert into scan_events (id, party_id, checkpoint, action, qty, voids_event_id, reason, override_reason, method,
                           actor_id, counter, device_id, client_at, app_version)
  values (eid, (p->>'partyId')::uuid, p->>'checkpoint', act, coalesce((p->>'qty')::int, 1), vid,
          nullif(p->>'reason', ''), nullif(p->>'overrideReason', ''), p->>'method',
          me.id, nullif(p->>'counter', ''), (p->>'deviceId')::uuid, cat, p->>'appVersion');
  return '{"status":"accepted"}'::jsonb;
end $$;

alter table device_status alter column user_id set not null;
alter table device_status drop constraint device_status_pkey;
alter table device_status add primary key (device_id, user_id);

create or replace function device_heartbeat(p_device_id uuid, p_counter text, p_pending_count int, p_app_version text, p_client_now timestamptz)
returns void language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_staff();
begin
  insert into device_status (device_id, user_id, counter, pending_count, app_version, last_sync_at, clock_offset_ms)
  values (p_device_id, me.id, p_counter, p_pending_count, p_app_version, now(),
          (extract(epoch from (now() - p_client_now)) * 1000)::int)
  on conflict (device_id, user_id) do update set counter = excluded.counter,
    pending_count = excluded.pending_count, app_version = excluded.app_version,
    last_sync_at = excluded.last_sync_at, clock_offset_ms = excluded.clock_offset_ms;
end $$;

-- ===== migrations/20261122000009_checkin_only.sql =====
-- Check-in only: the app no longer serves dinner. Apply this together with deploying the check-in-only app (the
-- refactor/checkin-only branch). Do NOT apply it while the earlier app, which records dinner scans, is still in use:
-- it would refuse those scans and break its stats.
--
-- Nothing is deleted. Old dinner scans (if any) stay in scan_events, so the append-only log keeps its history; the
-- 'dinner' checkpoint row stays too, because those rows point at it.
--
-- 1. party_state no longer has the dinner columns (served, last_served_at, over_served, served_without_entry), and a
--    party's entitlement is its party size. entitled_override stays in the parties table, unused.
-- 2. The server refuses any event that is not an entry check-in, including a void of an old dinner scan. A phone that
--    still has dinner scans waiting to sync will see them listed as "Not sent". Sync every phone before applying this.
-- 3. The dinner counters are switched off. They stay in the table so old scans can still show their names.

-- 1. The view. Same rule as src/lib/state.ts partyState(): live = entry passes that were not undone, earliest wins.
drop view party_state;
create view party_state with (security_invoker = true) as
with live as (
  select e.* from scan_events e
  where e.action = 'pass'
    and not exists (select 1 from scan_events v
                    where v.action = 'void' and v.voids_event_id = e.id)
),
entry as (
  select distinct on (party_id) party_id, client_at as entered_at, qty as headcount, counter
  from live where checkpoint = 'entry'
  order by party_id, client_at, received_at          -- earliest wins
),
entry_n as (select party_id, count(*) n from live where checkpoint = 'entry' group by 1)
select p.id as party_id,
  p.party_size                                              as entitled,
  (en.party_id is not null)                                 as entered,
  en.entered_at, en.headcount,
  coalesce(n.n, 0) > 1                                      as duplicate_entry,
  (p.possible_duplicate_of is not null)                     as possible_duplicate
from parties p
left join entry en on en.party_id = p.id
left join entry_n n on n.party_id = p.id
where p.deleted_at is null;
grant select on party_state to authenticated;

-- 2. Same function as migration 8, plus one line: only entry events are accepted.
create or replace function _push_event(me staff_users, p jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  eid uuid := (p->>'id')::uuid;
  act event_action := coalesce(p->>'action', 'pass')::event_action;
  vid uuid := nullif(p->>'voidsEventId', '')::uuid;
  cat timestamptz := to_timestamp((p->>'clientAt')::numeric / 1000.0);
  tgt scan_events;
begin
  if exists (select 1 from scan_events where id = eid) then return '{"status":"duplicate"}'::jsonb; end if;
  if coalesce(p->>'checkpoint', '') <> 'entry' then raise exception 'Only check-ins are recorded'; end if;
  if not exists (select 1 from parties where id = (p->>'partyId')::uuid) then raise exception 'Unknown party'; end if;
  if me.role = 'volunteer' and (p->>'method' = 'staff' or nullif(p->>'overrideReason', '') is not null) then
    raise exception 'Staff only';
  end if;
  if act = 'void' then
    select * into tgt from scan_events where id = vid;
    if not found or tgt.action <> 'pass' then raise exception 'Nothing to undo'; end if;
    if tgt.party_id <> (p->>'partyId')::uuid then raise exception 'That scan belongs to another guest'; end if;
    if exists (select 1 from scan_events where voids_event_id = vid) then raise exception 'Already undone'; end if;
    if me.role = 'volunteer' then
      if tgt.actor_id <> me.id then raise exception 'You can only undo your own scans'; end if;
      if tgt.device_id = (p->>'deviceId')::uuid then
        -- Same phone, one clock.
        if cat < tgt.client_at then raise exception 'That undo is dated before the scan'; end if;
        if cat - tgt.client_at > interval '120 seconds' then raise exception 'Undo window has passed'; end if;
      else
        -- Another phone: its clock can't be compared with the scan's, so use ours.
        if now() - tgt.received_at > interval '120 seconds' then raise exception 'Undo window has passed'; end if;
      end if;
    end if;
  end if;
  insert into scan_events (id, party_id, checkpoint, action, qty, voids_event_id, reason, override_reason, method,
                           actor_id, counter, device_id, client_at, app_version)
  values (eid, (p->>'partyId')::uuid, p->>'checkpoint', act, coalesce((p->>'qty')::int, 1), vid,
          nullif(p->>'reason', ''), nullif(p->>'overrideReason', ''), p->>'method',
          me.id, nullif(p->>'counter', ''), (p->>'deviceId')::uuid, cat, p->>'appVersion');
  return '{"status":"accepted"}'::jsonb;
end $$;

-- 3. Dinner counters off. The rows stay so old scans keep their counter names.
update counters set active = false where kind = 'dinner';

-- ===== migrations/20261122000010_flush_checkins.sql =====
-- Flush: an admin clears every check-in so everyone counts as not arrived again (rehearsals and dry runs). Run after
-- 20261122000009. It adds two functions and changes nothing that exists, so it is safe to apply while the earlier app
-- is still deployed.
--
-- How: one void event for every live check-in, written in a single transaction. scan_events stays append-only, nobody's
-- registration is touched, and every phone picks the voids up on its next pull, because a void is a new row with a
-- higher seq (a server delete would be invisible to phones that already hold the rows). The voids carry the reason
-- 'Flush: <why>', method 'staff' and one shared timestamp, so the app can show them as one line.
--
-- On-spot guests (registered in the app) can optionally be removed too: soft-deleted like a guest-list Replace, and
-- their contact rows deleted so a later registration with the same mobile is not flagged as a duplicate of them.
--
-- Same lock as push_batch, so the voids and any phone's scan are applied one after the other.

-- What a flush would do right now, plus phones that still have unsent items (their scans would arrive after the flush
-- and check people in again). device_status is a heartbeat: an offline phone's last report can be old.
create function admin_flush_preview() returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me staff_users := _require_role('admin'); parties_in int; people int; scans int; onspot int; phones jsonb;
begin
  select count(*), coalesce(sum(headcount), 0) into parties_in, people from party_state where entered;
  select count(*) into scans from scan_events e
    where e.action = 'pass' and e.checkpoint = 'entry'
      and not exists (select 1 from scan_events v where v.action = 'void' and v.voids_event_id = e.id);
  select count(*) into onspot from parties where source = 'onspot' and deleted_at is null;
  select coalesce(jsonb_agg(jsonb_build_object('counter', d.counter, 'pending', d.pending_count,
                                               'lastSyncAt', (extract(epoch from d.last_sync_at) * 1000)::bigint)
                            order by d.last_sync_at desc), '[]'::jsonb)
    into phones
  from device_status d
  where d.pending_count > 0 and d.last_sync_at > now() - interval '6 hours';
  return jsonb_build_object('checkedIn', parties_in, 'people', people, 'scans', scans, 'onSpot', onspot, 'phones', phones);
end $$;

create function admin_flush_checkins(p_reason text, p_remove_onspot boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('admin'); why text := btrim(coalesce(p_reason, '')); voided int; removed int := 0;
begin
  if length(why) < 3 then raise exception 'A reason is required'; end if;
  perform pg_advisory_xact_lock(1);
  perform set_config('app.reason', 'Flush: ' || why, true);

  insert into scan_events (id, party_id, checkpoint, action, qty, voids_event_id, reason, method, actor_id, device_id, client_at, app_version)
  select gen_random_uuid(), e.party_id, 'entry', 'void', 0, e.id, 'Flush: ' || why, 'staff', me.id, gen_random_uuid(), now(), 'server'
  from scan_events e
  where e.action = 'pass' and e.checkpoint = 'entry'
    and not exists (select 1 from scan_events v where v.action = 'void' and v.voids_event_id = e.id);
  get diagnostics voided = row_count;

  if p_remove_onspot then
    select count(*) into removed from parties where source = 'onspot' and deleted_at is null;
    update parties set deleted_at = now(), updated_by = me.id where source = 'onspot' and deleted_at is null;
    delete from party_contacts where party_id in (select id from parties where source = 'onspot' and deleted_at is not null);
  end if;

  insert into audit_log (actor_id, table_name, row_id, action, after, reason)
  values (me.id, 'scan_events', 'all', 'flush', jsonb_build_object('voided', voided, 'removedOnSpot', removed), why);
  return jsonb_build_object('voided', voided, 'removedOnSpot', removed);
end $$;

revoke execute on function admin_flush_preview(), admin_flush_checkins(text, boolean) from public, anon;
grant execute on function admin_flush_preview(), admin_flush_checkins(text, boolean) to authenticated;

-- ===== migrations/20261122000011_delete_user.sql =====
-- Delete a person from the staff list for good, but only when nothing on record points at them. Run after
-- 20261122000010. It adds one function and replaces admin_list_users (same output plus one key), so it is safe to apply
-- while the earlier app is deployed: that app ignores the extra key and has no delete button.
--
-- Switching someone off (admin_set_user with active = false) stays the normal way to remove access. A person who ever
-- scanned a guest, registered one, resolved a review, added another user or edited anything can't be deleted: those
-- records name them, and the log must keep saying who did what. Their own sign-in entries in the audit log do not
-- count (every account that ever signed in has one); those lose the pointer to the account, the entries stay.
--
-- Also: a request from an account that is switched off or no longer on the list now fails with 'Your account is switched
-- off or removed' instead of 'not authorised' (same error code). The check-in-only app uses that wording to tell this
-- apart from a role that is too low or a sign-in that ran out, and signs the phone out. The earlier app only looks at
-- the code, so it behaves as before. Until this migration is applied the new app falls back to the old behaviour (a
-- "please sign in again" banner).
--
-- The sign-in record in Supabase Authentication, Users is not touched. Without a staff_users row that account gets
-- "not on the list", and the sign-up hook still refuses new accounts for unlisted emails.

create or replace function _require_staff() returns staff_users language plpgsql stable security definer set search_path = public as $$
declare me staff_users;
begin
  select * into me from staff_users where auth_user_id = auth.uid() and active;
  if not found then raise exception 'Your account is switched off or removed' using errcode = '42501'; end if;
  return me;
end $$;

-- Private helper: does any record name this person?
create function _user_has_history(uid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from scan_events where actor_id = uid)
      or exists (select 1 from parties where created_by = uid or updated_by = uid)
      or exists (select 1 from review_resolutions where resolved_by = uid)
      or exists (select 1 from staff_users where created_by = uid)
      or exists (select 1 from audit_log where actor_id = uid and not (table_name = 'staff_users' and row_id = uid::text))
$$;

create or replace function admin_list_users() returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me staff_users := _require_role('admin');
begin
  return coalesce((select jsonb_agg(jsonb_build_object('email', email, 'name', coalesce(display_name, ''), 'role', role, 'active', active,
                                                       'canDelete', (id <> me.id and not _user_has_history(id)))
                                    order by role desc, email) from staff_users), '[]'::jsonb);
end $$;

create function admin_delete_user(p_email text) returns jsonb language plpgsql security definer set search_path = public as $$
declare me staff_users := _require_role('admin'); tgt staff_users;
begin
  select * into tgt from staff_users where email = lower(btrim(p_email));
  if not found then raise exception 'No such person'; end if;
  if tgt.id = me.id then raise exception 'You can''t delete yourself'; end if;
  if tgt.active then raise exception 'Switch them off first'; end if;
  if _user_has_history(tgt.id) then raise exception 'They have scans or edits on record, so they can only be switched off'; end if;
  perform set_config('app.reason', 'User deleted', true);
  update audit_log set actor_id = null where actor_id = tgt.id;
  delete from device_status where user_id = tgt.id;
  delete from staff_users where id = tgt.id;     -- the audit trigger records the deletion, with who did it
  return jsonb_build_object('email', tgt.email);
end $$;

revoke execute on function _user_has_history(uuid) from public, anon, authenticated;
revoke execute on function admin_delete_user(text) from public, anon;
grant execute on function admin_delete_user(text) to authenticated;

